import type { Metadata } from "next";
import { site } from "@/data/site";

export const abs = (path = "") => `${site.url.replace(/\/$/, "")}${path}`;

/** Default social share image (generated by src/app/opengraph-image.tsx). */
const DEFAULT_OG = "/opengraph-image";

/** Per-page metadata: unique title/description, canonical URL, Open Graph + Twitter cards. */
export function pageMeta({
  title,
  description,
  path,
  image,
  type = "website",
  absoluteTitle,
}: {
  title: string;
  description: string;
  path: string;
  image?: string | null;
  type?: "website" | "article";
  absoluteTitle?: boolean;
}): Metadata {
  const desc = description.replace(/\s+/g, " ").trim().slice(0, 158);
  const full = absoluteTitle ? title : `${title} | ${site.name}`;
  const img = image || DEFAULT_OG;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description: desc,
    alternates: { canonical: path },
    openGraph: { title: full, description: desc, url: path, siteName: site.name, type, locale: "en_IN", images: [{ url: img, alt: title }] },
    twitter: { card: "summary_large_image", title: full, description: desc, images: [img] },
  };
}

export function breadcrumbLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((it, i) => ({ "@type": "ListItem", position: i + 1, name: it.name, item: abs(it.path) })),
  };
}
